{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "S3 public ACLs are not blocked",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "HIGH",
      "explanation": "The block_public_acls setting is omitted and therefore defaults to false, allowing public ACLs to be applied to the referenced bucket."
    },
    {
      "check_id": "CKV_AWS_54",
      "title": "S3 public bucket policies are not blocked",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "HIGH",
      "explanation": "The block_public_policy setting is omitted and defaults to false, allowing policies that grant public access to the bucket."
    },
    {
      "check_id": "CKV_AWS_55",
      "title": "S3 public ACLs are not ignored",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "HIGH",
      "explanation": "The ignore_public_acls setting is omitted and defaults to false, so existing public ACL grants may remain effective."
    },
    {
      "check_id": "CKV_AWS_56",
      "title": "S3 public bucket access is not restricted",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "HIGH",
      "explanation": "restrict_public_buckets is explicitly false, permitting public policies to expose the referenced bucket."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"api_docs\" {\n  bucket                  = aws_s3_bucket.api_docs.id\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}\n",
  "fix_summary": "Enabled all four S3 Block Public Access controls to prevent public access through ACLs or bucket policies."
}
